import { GoogleGenAI, Type } from "@google/genai";

// Initialize the client. 
// Note: We create a new instance in functions that require user-selected keys to ensure freshness.
const getAiClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateWittyComment = async (videoDescription: string): Promise<string> => {
  try {
    const ai = getAiClient();
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Read this video description: "${videoDescription}". Generate a short, funny, and engaging TikTok-style comment (max 15 words) that a user might leave. Include 1 emoji.`,
    });
    return response.text || "Wow! 😍";
  } catch (error) {
    console.error("Gemini comment error:", error);
    return "This is awesome! 🔥";
  }
};

export const explainVideoTopic = async (videoDescription: string): Promise<string> => {
  try {
    const ai = getAiClient();
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Explain the likely topic and context of a video with this description: "${videoDescription}". Keep it to one concise sentence.`,
    });
    return response.text || "Interesting content!";
  } catch (error) {
    console.error("Gemini explain error:", error);
    return "A cool video.";
  }
};

export const generateVeoVideo = async (prompt: string): Promise<string | null> => {
  // Check for API key selection before proceeding (though UI should handle this too)
  if (window.aistudio && await window.aistudio.hasSelectedApiKey()) {
     // Re-instantiate to grab the selected key
     const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

     try {
       let operation = await ai.models.generateVideos({
         model: 'veo-3.1-fast-generate-preview', // Fast model for quicker demos
         prompt: prompt,
         config: {
           numberOfVideos: 1,
           resolution: '720p',
           aspectRatio: '9:16' // Portrait for TikTok
         }
       });

       // Poll for completion
       while (!operation.done) {
         await new Promise(resolve => setTimeout(resolve, 5000)); // Poll every 5s
         operation = await ai.operations.getVideosOperation({ operation: operation });
       }

       const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
       if (!downloadLink) return null;

       // We must fetch it with the key to get the actual blob/url usable in <video> src
       // For this demo, we will return the proxy URL pattern or handle the fetch in the component.
       // The instructions say: fetch(`${downloadLink}&key=${process.env.API_KEY}`)
       // We will return the URL string, and the component can fetch it to a Blob URL.
       return `${downloadLink}&key=${process.env.API_KEY}`;

     } catch (error) {
       console.error("Veo generation error:", error);
       throw error;
     }
  } else {
    throw new Error("API Key not selected");
  }
};

import React, { useRef, useEffect, useState } from 'react';
import { Heart, MessageCircle, Share2, Disc, Music, UserPlus } from 'lucide-react';
import { VideoData } from '../types';

interface VideoPlayerProps {
  data: VideoData;
  isActive: boolean;
  onShowComments: () => void;
}

const VideoPlayer: React.FC<VideoPlayerProps> = ({ data, isActive, onShowComments }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [liked, setLiked] = useState(false);
  const [likeCount, setLikeCount] = useState(data.likes);

  useEffect(() => {
    if (isActive) {
      // Play with a slight delay to ensure smooth scroll snapping
      const timer = setTimeout(() => {
        videoRef.current?.play().catch(e => console.log('Autoplay blocked', e));
        setIsPlaying(true);
      }, 300);
      return () => clearTimeout(timer);
    } else {
      videoRef.current?.pause();
      if (videoRef.current) videoRef.current.currentTime = 0;
      setIsPlaying(false);
    }
  }, [isActive]);

  const togglePlay = () => {
    if (videoRef.current) {
      if (isPlaying) {
        videoRef.current.pause();
      } else {
        videoRef.current.play();
      }
      setIsPlaying(!isPlaying);
    }
  };

  const handleLike = () => {
    setLiked(!liked);
    setLikeCount(prev => liked ? prev - 1 : prev + 1);
  };

  return (
    <div className="relative w-full h-full bg-black snap-start shrink-0 flex items-center justify-center overflow-hidden">
      {/* Video Element */}
      <video
        ref={videoRef}
        src={data.url}
        className="w-full h-full object-cover"
        loop
        playsInline
        muted={false} // In a real app, handle mute state globally. Browser might block unmuted autoplay.
        onClick={togglePlay}
      />

      {/* Play Icon Overlay (when paused) */}
      {!isPlaying && (
        <div 
          className="absolute inset-0 flex items-center justify-center bg-black/20 pointer-events-none"
        >
          <div className="w-16 h-16 bg-white/20 rounded-full flex items-center justify-center backdrop-blur-sm">
            <div className="w-0 h-0 border-t-[10px] border-t-transparent border-l-[20px] border-l-white border-b-[10px] border-b-transparent ml-1"></div>
          </div>
        </div>
      )}

      {/* Right Sidebar Actions */}
      <div className="absolute right-2 bottom-20 flex flex-col items-center space-y-6 z-20">
        {/* Avatar */}
        <div className="relative mb-2">
          <div className="w-12 h-12 rounded-full border-2 border-white p-[1px] overflow-hidden">
            <img src={data.user.avatar} alt={data.user.username} className="w-full h-full object-cover rounded-full" />
          </div>
          <div className="absolute -bottom-2 left-1/2 transform -translate-x-1/2 bg-primary w-5 h-5 rounded-full flex items-center justify-center">
             <UserPlus size={12} className="text-white" />
          </div>
        </div>

        {/* Like */}
        <div className="flex flex-col items-center space-y-1">
          <button onClick={handleLike} className="transition-transform active:scale-75">
            <Heart 
              size={32} 
              className={`transition-colors duration-300 ${liked ? 'fill-primary text-primary' : 'text-white drop-shadow-md'}`} 
            />
          </button>
          <span className="text-white text-xs font-semibold drop-shadow-md">{likeCount.toLocaleString()}</span>
        </div>

        {/* Comment */}
        <div className="flex flex-col items-center space-y-1">
          <button onClick={onShowComments} className="transition-transform active:scale-75">
            <MessageCircle size={32} className="text-white drop-shadow-md" />
          </button>
          <span className="text-white text-xs font-semibold drop-shadow-md">{data.comments}</span>
        </div>

        {/* Share */}
        <div className="flex flex-col items-center space-y-1">
          <button className="transition-transform active:scale-75">
            <Share2 size={32} className="text-white drop-shadow-md" />
          </button>
          <span className="text-white text-xs font-semibold drop-shadow-md">{data.shares}</span>
        </div>

        {/* Spinning Disc */}
        <div className="relative mt-4 animate-spin-slow">
            <div className="w-12 h-12 bg-gray-800 rounded-full flex items-center justify-center border-[6px] border-gray-900">
                <img src={data.user.avatar} className="w-6 h-6 rounded-full object-cover" alt="music" />
            </div>
        </div>
      </div>

      {/* Bottom Info */}
      <div className="absolute left-0 bottom-0 w-full pl-4 pr-16 pb-6 bg-gradient-to-t from-black/60 to-transparent z-10 pointer-events-none">
        <div className="mb-2">
          <h3 className="text-white font-bold text-lg drop-shadow-md pointer-events-auto inline-block cursor-pointer hover:underline">
            @{data.user.username}
          </h3>
        </div>
        <div className="mb-3">
          <p className="text-white text-sm drop-shadow-md line-clamp-2">
            {data.description}
          </p>
        </div>
        <div className="flex items-center space-x-2 text-white/90">
          <Music size={14} className="animate-pulse" />
          <div className="overflow-hidden w-2/3">
             <p className="text-xs whitespace-nowrap animate-marquee">
               {data.songName} • {data.songArtist}
             </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default VideoPlayer;

import React, { useState, useEffect } from 'react';
import { X, Send, Sparkles, User } from 'lucide-react';
import { Comment, VideoData } from '../types';
import { MOCK_COMMENTS } from '../constants';
import { generateWittyComment } from '../services/geminiService';

interface CommentsSheetProps {
  video: VideoData | null;
  isOpen: boolean;
  onClose: () => void;
}

const CommentsSheet: React.FC<CommentsSheetProps> = ({ video, isOpen, onClose }) => {
  const [comments, setComments] = useState<Comment[]>(MOCK_COMMENTS);
  const [inputValue, setInputValue] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);

  useEffect(() => {
    // Reset when opening for a new video (in a real app, fetch comments for videoId)
    setComments(MOCK_COMMENTS);
    setInputValue('');
  }, [video?.id]);

  const handleSend = () => {
    if (!inputValue.trim()) return;

    const newComment: Comment = {
      id: Date.now().toString(),
      user: { id: 'me', username: 'you', avatar: 'https://picsum.photos/50/50?me' },
      text: inputValue,
      likes: 0,
      timestamp: 'now',
    };

    setComments([newComment, ...comments]);
    setInputValue('');
  };

  const handleMagicComment = async () => {
    if (!video) return;
    setIsGenerating(true);
    const magicText = await generateWittyComment(video.description);
    setInputValue(magicText);
    setIsGenerating(false);
  };

  if (!isOpen) return null;

  return (
    <div className="absolute inset-0 z-50 flex flex-col justify-end bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
      <div 
        className="w-full h-[70%] bg-gray-900 rounded-t-2xl flex flex-col shadow-2xl animate-in slide-in-from-bottom duration-300"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-gray-800">
          <div className="w-8" /> {/* Spacer */}
          <h2 className="text-sm font-bold text-white">
            {comments.length} comments
          </h2>
          <button onClick={onClose} className="p-1">
            <X size={20} className="text-gray-400" />
          </button>
        </div>

        {/* Scrollable List */}
        <div className="flex-1 overflow-y-auto p-4 space-y-6">
          {comments.map((comment) => (
            <div key={comment.id} className="flex space-x-3">
              <img src={comment.user.avatar} className="w-8 h-8 rounded-full bg-gray-700 object-cover" alt="avatar" />
              <div className="flex-1">
                <p className="text-xs font-semibold text-gray-400 mb-0.5">{comment.user.username}</p>
                <p className="text-sm text-white">{comment.text}</p>
                <div className="flex items-center space-x-4 mt-2">
                  <span className="text-xs text-gray-500">{comment.timestamp}</span>
                  <span className="text-xs text-gray-500 font-semibold cursor-pointer">Reply</span>
                </div>
              </div>
              <div className="flex flex-col items-center space-y-1 pt-2">
                 <HeartIcon filled={false} />
                 <span className="text-[10px] text-gray-500">{comment.likes}</span>
              </div>
            </div>
          ))}
        </div>

        {/* Input Area */}
        <div className="p-4 border-t border-gray-800 flex items-center space-x-3 bg-gray-900 pb-8">
          <img src="https://picsum.photos/50/50?me" className="w-8 h-8 rounded-full bg-gray-700" alt="me" />
          <div className="flex-1 relative">
            <input
              type="text"
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              placeholder="Add comment..."
              className="w-full bg-gray-800 text-white text-sm rounded-full py-2.5 pl-4 pr-10 focus:outline-none focus:ring-1 focus:ring-gray-600"
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            />
            <button 
                onClick={handleMagicComment}
                className="absolute right-2 top-1/2 -translate-y-1/2 p-1.5 rounded-full hover:bg-gray-700 transition-colors"
                disabled={isGenerating}
            >
                {isGenerating ? (
                    <div className="w-4 h-4 border-2 border-primary border-t-transparent rounded-full animate-spin" />
                ) : (
                    <Sparkles size={16} className="text-secondary" />
                )}
            </button>
          </div>
          <button 
            onClick={handleSend} 
            disabled={!inputValue.trim()}
            className={`p-2 rounded-full ${inputValue.trim() ? 'bg-primary text-white' : 'bg-gray-800 text-gray-600'}`}
          >
            <Send size={18} />
          </button>
        </div>
      </div>
    </div>
  );
};

