export default CommentsSheet;

import React, { useState, useEffect } from 'react';
import { Film, Loader2, Play, AlertTriangle } from 'lucide-react';
import { generateVeoVideo } from '../services/geminiService';

const CreateView: React.FC = () => {
  const [prompt, setPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedVideoUrl, setGeneratedVideoUrl] = useState<string | null>(null);
  const [hasKey, setHasKey] = useState<boolean>(false);
  const [keyError, setKeyError] = useState<boolean>(false);
  const [statusMessage, setStatusMessage] = useState('');
  const [videoBlobUrl, setVideoBlobUrl] = useState<string | null>(null);

  useEffect(() => {
    checkKey();
  }, []);

  const checkKey = async () => {
    try {
      if (window.aistudio && await window.aistudio.hasSelectedApiKey()) {
        setHasKey(true);
        setKeyError(false);
      } else {
        setHasKey(false);
      }
    } catch (e) {
      console.error(e);
      setKeyError(true);
    }
  };

  const handleSelectKey = async () => {
    if (window.aistudio) {
        try {
            await window.aistudio.openSelectKey();
            // Race condition mitigation: assume success if no error thrown
            setHasKey(true);
            setKeyError(false);
        } catch (e) {
            console.error(e);
            setKeyError(true);
        }
    }
  };

  const handleGenerate = async () => {
    if (!prompt.trim() || !hasKey) return;

    setIsGenerating(true);
    setGeneratedVideoUrl(null);
    setVideoBlobUrl(null);
    setStatusMessage('Connecting to Veo 3.1...');

    try {
      const url = await generateVeoVideo(prompt);
      if (url) {
        setStatusMessage('Downloading video...');
        // Fetch the content to create a blob URL because the raw URL needs the key appended
        // and <video> src with key in param might be insecure or tricky with CORS if not handled.
        // However, for this demo, let's try fetching it.
        const response = await fetch(url);
        if (!response.ok) throw new Error("Failed to download generated video");
        const blob = await response.blob();
        const blobUrl = URL.createObjectURL(blob);
        setVideoBlobUrl(blobUrl);
        setGeneratedVideoUrl(url); // Keep raw just in case
        setStatusMessage('Done!');
      } else {
        setStatusMessage('Generation failed.');
      }
    } catch (error) {
      console.error(error);
      setStatusMessage('Error generating video. Try again.');
      // If error suggests key issues
      if (error instanceof Error && error.message.includes('403') || error.message.includes('not found')) {
          setHasKey(false);
          setKeyError(true);
      }
    } finally {
      setIsGenerating(false);
    }
  };

  if (!hasKey) {
      return (
          <div className="flex flex-col items-center justify-center h-full p-8 text-center bg-black">
              <Film size={64} className="text-gray-600 mb-6" />
              <h2 className="text-2xl font-bold mb-4">Create with Veo</h2>
              <p className="text-gray-400 mb-8 max-w-xs">
                  To generate AI videos, you need to connect your Google Cloud project with billing enabled.
              </p>
              <button 
                onClick={handleSelectKey}
                className="bg-primary text-white font-bold py-3 px-8 rounded-full shadow-lg hover:bg-red-600 transition-colors"
              >
                  Select API Key
              </button>
              {keyError && (
                  <p className="text-red-500 mt-4 text-sm flex items-center">
                      <AlertTriangle size={14} className="mr-1" />
                      Selection failed or cancelled. Please try again.
                  </p>
              )}
              <a 
                href="https://ai.google.dev/gemini-api/docs/billing" 
                target="_blank" 
                rel="noreferrer"
                className="mt-8 text-xs text-gray-500 underline"
              >
                  Learn about billing
              </a>
          </div>
      )
  }

  return (
    <div className="h-full flex flex-col bg-black p-6 pt-12 overflow-y-auto">
      <h2 className="text-2xl font-bold mb-6 flex items-center">
          <Film className="mr-2 text-primary" />
          AI Studio
      </h2>

      <div className="space-y-4">
        <label className="block text-gray-400 text-sm font-semibold">
            Prompt
        </label>
        <textarea
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            placeholder="Describe the video you want to create... e.g., A cyberpunk cat walking in Tokyo rain."
            className="w-full h-32 bg-gray-900 border border-gray-800 rounded-xl p-4 text-white focus:border-secondary focus:outline-none resize-none"
        />

        <button
            onClick={handleGenerate}
            disabled={isGenerating || !prompt.trim()}
            className={`w-full py-4 rounded-xl font-bold text-lg flex items-center justify-center space-x-2 transition-all ${
                isGenerating || !prompt.trim() 
                ? 'bg-gray-800 text-gray-500 cursor-not-allowed' 
                : 'bg-gradient-to-r from-primary to-secondary text-black shadow-lg hover:shadow-primary/50'
            }`}
        >
            {isGenerating ? (
                <>
                    <Loader2 className="animate-spin" />
                    <span>{statusMessage}</span>
                </>
            ) : (
                <>
                    <Play fill="currentColor" />
                    <span>Generate Video</span>
                </>
            )}
        </button>

        {isGenerating && (
            <p className="text-center text-xs text-gray-500 animate-pulse">
                Veo video generation can take 1-2 minutes. Please stay on this screen.
            </p>
        )}
      </div>

      {/* Result Display */}
      {videoBlobUrl && (
          <div className="mt-8">
              <h3 className="text-white font-bold mb-3">Result</h3>
              <div className="relative rounded-2xl overflow-hidden border border-gray-800 aspect-[9/16] bg-gray-900 shadow-2xl">
                  <video 
                    src={videoBlobUrl} 
                    controls 
                    autoPlay 
                    loop 
                    className="w-full h-full object-cover"
                  />
                  <div className="absolute top-2 right-2 bg-black/60 px-2 py-1 rounded text-xs font-mono text-secondary border border-secondary/30">
                      Generated by Veo
                  </div>
              </div>
              <button 
                onClick={() => setVideoBlobUrl(null)}
                className="mt-4 w-full py-3 text-sm text-gray-400 font-semibold hover:text-white"
              >
                  Clear & Create New
              </button>
          </div>
      )}
    </div>
  );
};

export default CreateView;

import React, { useState, useRef, useEffect } from 'react';
import VideoPlayer from './VideoPlayer';
