import { VideoData } from '../types';

const VideoFeed: React.FC = () => {
  const [activeIndex, setActiveIndex] = useState(0);
  const containerRef = useRef<HTMLDivElement>(null);
  const [showComments, setShowComments] = useState(false);
  const [currentVideoForComments, setCurrentVideoForComments] = useState<VideoData | null>(null);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const handleScroll = () => {
      const index = Math.round(container.scrollTop / container.clientHeight);
      if (index !== activeIndex) {
        setActiveIndex(index);
      }
    };

    container.addEventListener('scroll', handleScroll);
    return () => container.removeEventListener('scroll', handleScroll);
  }, [activeIndex]);

  const handleShowComments = (video: VideoData) => {
    setCurrentVideoForComments(video);
    setShowComments(true);
  };

  return (
    <div className="relative h-full w-full bg-black">
      {/* Scroll Container */}
      <div 
        ref={containerRef}
        className="h-full w-full overflow-y-scroll snap-y snap-mandatory no-scrollbar"
        style={{ scrollBehavior: 'smooth' }}
      >
        {MOCK_VIDEOS.map((video, index) => (
          <div key={video.id} className="w-full h-full snap-start">
             <VideoPlayer 
                data={video} 
                isActive={activeIndex === index} 
                onShowComments={() => handleShowComments(video)}
             />
          </div>
        ))}

        {/* Mocking infinite load buffer */}
        <div className="w-full h-24 flex items-center justify-center snap-start text-gray-500 text-sm">
            <p>You've reached the end for now!</p>
        </div>
      </div>

      {/* Top Overlay Tabs (Following/For You) */}
      <div className="absolute top-6 left-0 w-full z-20 flex justify-center space-x-4 pt-4">
        <button className="text-gray-400 font-bold text-base hover:text-white transition-colors">Following</button>
        <div className="w-[1px] h-4 bg-gray-600 self-center"></div>
        <button className="text-white font-bold text-lg border-b-2 border-white pb-0.5 shadow-sm">For You</button>
      </div>

      <CommentsSheet 
        video={currentVideoForComments}
        isOpen={showComments}
        onClose={() => setShowComments(false)}
      />
    </div>
  );
};

export default VideoFeed;

